declare 

begin
  select count(*)  into :v_count from bankm_test where bankcode=:v_bankcode and val_code=:v_val_code;

 if :v_count>0 then
 update bankm_test set
 krno=:v_krno, name=:v_name, inn=:v_inn, swift=:v_swift,
 bankcode=:v_bankcode, subkrno=:v_subkrno, ours=:v_ours, val_code=:v_val_code
 where  bankcode=:v_bankcode and  val_code=:v_val_code;

 else

insert into  bankm_test  (krno, name, inn, swift, bankcode, subkrno, ours, val_code)
                  values (:v_krno, :v_name, :v_inn, :v_swift, :v_bankcode, :v_subkrno, :v_ours, :v_val_code);
 end if;
commit;
end;

